pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address owner, address spender) public {
        // Record totalSupply before the call
        uint256 totalSupplyBefore = c.totalSupply();

        // Call allowance (this does not modify totalSupply in the correct contract)
        c.allowance(owner, spender);

        // After allowance, totalSupply should equal totalSupplyBefore
        assertTrue(c.totalSupply() == totalSupplyBefore);
    }
}

