pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address a1, address a2, address a3, uint256 amount) public {
        vm.assume(a1 != address(0) && a2 != address(0) && a3 != address(0));
        vm.assume(amount <= 1000 ether);

        // Record totalSupply before any action
        uint256 supplyBefore = c.totalSupply();

        // Perform allowance call
        c.allowance(a1, a2);

        // Record totalSupply after allowance call
        uint256 supplyAfterAllowance = c.totalSupply();

        // Now perform a burn(0) to trigger _burn logic
        vm.prank(a3);
        c.burn(0);

        // Record totalSupply after burn(0)
        uint256 supplyAfterBurn = c.totalSupply();

        // The general rule: totalSupply after allowance() equals totalSupply after a harmless burn(0)
        // In the reference, both should equal the initial supply. In the mutant, allowance() incorrectly decrements totalSupply.
        assertTrue(supplyAfterAllowance == supplyAfterBurn, "totalSupply changed after allowance");
    }
}

