pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account1, address account2, uint256 amount) public {
        vm.assume(account1 != address(0) && account2 != address(0) && account1 != account2);
        vm.assume(amount > 0 && amount < type(uint256).max / 2);

        // Perform some operations to change state
        c.mintSynth(account1, amount);
        c.transfer(account2, amount / 2);
        c.approve(account1, amount);
        c.transferFrom(account2, account1, amount / 4);

        // Call allowance as specified
        c.allowance(account1, account2);

        // General rule: totalSupply must equal sum of all balances
        // Since we cannot iterate all accounts, we use a proxy: if totalSupply is sum of known balances
        // plus balance of address(this) (the deployer/contract itself), then invariant holds.
        uint256 totalBalance = c.balanceOf(account1) + c.balanceOf(account2) + c.balanceOf(address(this));
        assertTrue(c.totalSupply() == totalBalance, "totalSupply != sum of balances");
    }
}

