pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);

        // Do some transfers to create balances
        c.transfer(addr1, 100);
        c.transfer(addr2, 200);

