import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address spender, address owner, uint256 amount) public {
        vm.assume(caller != address(0) && spender != address(0) && owner != address(0));
        vm.assume(amount < 1e30);

        // Drive the contract: first approve some spend
        vm.prank(owner);
        c.approve(spender, amount);

        // Now call allowance – the final operation
        c.allowance(owner, spender);

        // General rule: For any address k, if mapSynth_LPBalance[k] != 0, then k must be a key that was 
        // explicitly set by the contract's public functions. Since only mintSynth (restricted) modifies it,
        // and we never called mintSynth, all nonzero entries must belong to keys we never touched.
        // The bug inserts a spurious nonzero entry at address(0), so check that mapSynth_LPBalance at 
        // address(0) is zero (unless some other public function set it, which none does).

        // Since we never called mintSynth, the only possible nonzero at address(0) would be from the bug.
        // But we cannot directly read mapSynth_LPBalance. However, we can observe it through the public getter.
        // The property: after any call sequence ending with allowance, mapSynth_LPBalance[address(0)] should be 0.
        // Because no legitimate call path can set that to nonzero (mintSynth is onlyPool and we never call it).

        // Use vm.prank to call as a pool? No, we cannot bypass onlyPool. So this check is valid:
        // Since we never called mintSynth, the getter must return 0 for the bug's inserted key.

        assertTrue(c.getmapAddress_LPBalance(address(0)) == 0);
    }
}

