        vm.assume(pool != address(0) && sender != address(0) && recipient != address(0));
        vm.assume(sender != recipient);

        // Setup: pre-fund sender with ERC20 tokens (using cheatcodes to simulate actual transfer)
        vm.deal(sender, 10**20);

        // Pre-call snapshot of mapSynth_LPDebt for the pool
        uint256 preLpDebt = c.getmapAddress_LPDebt(pool);

        // Pre-call snapshot of mapSynth_LPBalance for the pool
        uint256 preLpBalance = c.getmapAddress_LPBalance(pool);

        // Call allowance to trigger state changes
        c.approve(sender, amount);
        c.transferFrom(sender, recipient, amount);

        // After allowance call, check mapSynth_LPDebt
        uint256 postLpDebt = c.getmapAddress_LPDebt(pool);

        // Compute maximum possible decrease based on logic
        // The rule: postLpDebt >= preLpDebt - (preLpBalance * (amount)) / (preLpDebt if nonzero else 1)
        uint256 maxDecrease;
        if (preLpDebt > 0) {
            maxDecrease = (preLpBalance * amount) / preLpDebt;
        } else {
            maxDecrease = 0;
        }

        // Assert that debt did not decrease more than allowed
        assertTrue(postLpDebt >= preLpDebt - maxDecrease, "Debt decreased more than allowed");
    }
}

